/* Lot 111: lh against the element's line-height (generated by scripts/lot111_gen.py; expectations from scripts/lot111_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048];
static char g_o[512];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(5, g_d.nnodes);
}

/* the line heights the reader keeps for body, #o and #i (px
 * thousandths + 1, 0 for normal) */
static const char *lh3(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d", g_d.lh[2], g_d.lh[3], g_d.lh[4]);
    return g_o;
}

/* the height (px) in the style passed for the element with that id,
 * -1 when it has none */
static int height_of(const char *id) {
    int i, v = -1;
    const char *h;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    h = strstr(g_o, ";height:");
    if (!h) h = strstr(g_o, "\"height:");
    if (h) sscanf(h + 8, "%d", &v);
    return v;
}

static void test_l111_lh_0(void) {
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { line-height: max(1em, 18px); line-height: 0.8 } #o { overflow: auto; height: 4lh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 0 12801", lh3());
    TEST_ASSERT_EQUAL(40, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } html { font-size: 16px } #i { line-height: 120%; line-height: 120% } body { font-size: 1.25em } #o { line-height: calc(1em + 4px); overflow: auto; height: 2.5lh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 24001 24001", lh3());
    TEST_ASSERT_EQUAL(60, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 2em; line-height: initial; line-height: calc(2 * 1.5em) } html { font-size: 10px; line-height: 0.8 } body { line-height: 0.8; line-height: unset } #o { font-size: 2em; line-height: initial; line-height: 0; overflow: auto; height: max(2lh, 30px) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("8001 1 120001", lh3());
    TEST_ASSERT_EQUAL(30, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 2em } #o { overflow: auto; height: 1lh } body { font-size: 32px; line-height: unset } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL(20, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { overflow: auto; height: min(5lh, 100px) } #i { line-height: max(1em, 18px) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 0 18001", lh3());
    TEST_ASSERT_EQUAL(50, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: 20px; line-height: 120%; overflow: auto; height: 0.5lh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 24001 24001", lh3());
    TEST_ASSERT_EQUAL(12, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { line-height: calc(10% + 1px); line-height: 120%; overflow: auto; height: 4lh } #i { font-size: 32px; line-height: inherit } body { font-size: 24px; line-height: normal } html { line-height: 10vh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 28801 28801", lh3());
    TEST_ASSERT_EQUAL(115, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { overflow: auto; height: calc(3lh - 1em) } body { font-size: 20px } html { font-size: 20px; line-height: 150% } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("30001 30001 30001", lh3());
    TEST_ASSERT_EQUAL(70, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 16px } body { line-height: 120%; line-height: 1.25 } #o { font-size: 1.25em; line-height: unset; overflow: auto; height: 10lh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("20001 25001 20001", lh3());
    TEST_ASSERT_EQUAL(250, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 2em } #o { overflow: auto; height: calc(1lh * 3) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL(30, height_of("o"));
}

